import json;l=[];l.append("import urllib.request, json, sys, time");l.append("BASE = sys.argv[1] if len(sys.argv) > 1 else 'http://localhost:8080'");l.append("");l.append("def test(name, payload):");l.append("    t0 = time.time()");l.append("    body = json.dumps(payload).encode()");l.append("    req = urllib.request.Request(BASE + '/webhook/feishu', data=body, method='POST')");l.append("    try:");l.append("        r = urllib.request.urlopen(req, timeout=120)");l.append("        d = json.loads(r.read())");l.append("        ok = r.status == 200");l.append("        if ok:");l.append("            print('[PASS] ' + name + ' (' + str(round(time.time()-t0,1)) + 's)')");l.append("        else:");l.append("            print('[FAIL] ' + name + ' (' + str(round(time.time()-t0,1)) + 's)')");l.append("        if 'text' in d: print('  reply: ' + d['text'][:100])");l.append("        if 'error' in d: print('  error: ' + d['error'] + ': ' + str(d.get('detail',''))[:150])");l.append("    except urllib.error.HTTPError as e:");l.append("        print('[FAIL] ' + name + ' HTTP ' + str(e.code))");l.append("        print('  body: ' + e.read().decode('utf-8', errors='replace')[:200])");l.append("");l.append("print('=== MoA Gateway Test ===')");l.append("print('Target: ' + BASE)");l.append("print()");l.append("r = urllib.request.urlopen(BASE + '/health', timeout=5)");l.append("print('[PASS] health: ' + str(json.loads(r.read())))");l.append("print()");l.append("test('greeting', {'session_id':'t1','text':'hello','message_id':'m1'})");l.append("test('coding', {'session_id':'t2','text':'write a python function','message_id':'m2'})");l.append("test('cancel', {'session_id':'t3','text':'cancel','message_id':'m3'})");l.append("print()");l.append("print('=== Done ===')");open('D:/HermesData/moa-gateway/scripts/test_webhook.py','w',encoding='utf-8').write('\n'.join(l));print('OK')